/* @autogenerated */
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { ThemeAssetRepository } from 'app/features/template/theme-asset/repository/theme-asset-repository.service';
import { ThemeAsset } from 'app/features/template/theme-asset/model/theme-asset.model';
import {
  THEME_ASSET_EXCEL_SENSITIVE,
  THEME_ASSET_EXCEL_COLUMNS,
} from 'app/features/template/theme-asset/model/theme-asset-excel-columns';
import { take, map } from 'rxjs';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { ThemeRepository } from 'app/features/template/theme/repository/theme-repository.service';
import { Component, inject } from '@angular/core';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'theme-asset-view-import-action',
  standalone: false,
  templateUrl: './theme-asset-view-import-action.component.html',
})
export class ThemeAssetViewImportActionComponent extends BaseImportAction<ThemeAsset> {
  protected readonly scope = 'template/theme-asset';
  protected readonly repository = inject(ThemeAssetRepository);
  private readonly themeRepository = inject(ThemeRepository);

  readonly definition: ImportDefinition<ThemeAsset> = {
    storageKey: 'template.theme-asset',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['code', 'theme'],
    columns: THEME_ASSET_EXCEL_COLUMNS,
    sensitive: THEME_ASSET_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      enabled: [
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
      ],
    },
    references: {
      theme: {
        resolve: (text) =>
          this.themeRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({ enabled: true }),
    display: (values) => String(values.code ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            code: values.code,
            theme: values.theme?.$ref ? [values.theme.$ref] : undefined,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) => item.code === values.code && (!values.theme?.$ref || item.theme?.$ref === values.theme.$ref),
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
